arguments:
$ErrorActionPreference = 'Stop'
$taskName = 'Codex_Capture_FullDesktop_20260904T1540'
$scriptPath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\Capture-InteractiveDesktop-20260904T1540.ps1'
$outputPath = 'C:\Assets\AssetValidation\AssetValidation-20260904T103354\remote-fullscreen-20260904T1540.png'
$user = 'DESKTOP-5OJC3K4\Song'
if (-not (Test-Path -LiteralPath $scriptPath -PathType Leaf)) { throw ('Capture script not found: ' + $scriptPath) }
if (Test-Path -LiteralPath $outputPath) { throw ('Refusing to overwrite: ' + $outputPath) }
$quote = [char]34
$arguments = '-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File ' + $quote + $scriptPath + $quote + ' -OutputPath ' + $quote + $outputPath + $quote
$action = New-ScheduledTaskAction -Execute 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe' -Argument $arguments
$principal = New-ScheduledTaskPrincipal -UserId $user -LogonType Interactive -RunLevel Limited
$settings = New-ScheduledTaskSettingsSet -ExecutionTimeLimit (New-TimeSpan -Minutes 2) -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries
try {
 Register-ScheduledTask -TaskName $taskName -Action $action -Principal $principal -Settings $settings -Force | Out-Null
 Start-ScheduledTask -TaskName $taskName
 $deadline = (Get-Date).AddSeconds(30)
 while ((Get-Date) -lt $deadline -and -not (Test-Path -LiteralPath $outputPath -PathType Leaf)) { Start-Sleep -Milliseconds 500 }
 if (-not (Test-Path -LiteralPath $outputPath -PathType Leaf)) {
  $info = Get-ScheduledTaskInfo -TaskName $taskName
  throw ('Screenshot was not created. LastTaskResult=' + $info.LastTaskResult)
 }
 $file = Get-Item -LiteralPath $outputPath
 $hash = Get-FileHash -LiteralPath $outputPath -Algorithm SHA256
 [pscustomobject]@{OutputPath=$file.FullName;Length=$file.Length;SHA256=$hash.Hash;InteractiveUser=$user;CapturedAt=$file.LastWriteTime.ToString('o')} | Format-List
} finally {
 Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue
}
